const vendors = $('Get Vendor Accounts').all();
const prop = (p, n) => (p && p.properties && p.properties[n]) ? p.properties[n] : null;
const titleText = (p, n) => { const x = prop(p, n); return x && Array.isArray(x.title) ? x.title.map(t => t.plain_text).join('') : ''; };
const emailOf = (p, n) => { const x = prop(p, n); return x && x.email ? x.email : ''; };
const multi = (p, n) => { const x = prop(p, n); return x && Array.isArray(x.multi_select) ? x.multi_select.map(o => o.name) : []; };
const cbOf = (p, n) => { const x = prop(p, n); return x && x.checkbox === true; };
const out = [];
for (const it of vendors) {
  const v = it.json;
  if (cbOf(v, 'Commission Notice Sent')) continue;
  const email = emailOf(v, 'Email');
  if (!email) continue;
  const vendorName = titleText(v, 'Vendor Name') || 'شركاءنا الكرام';
  const cities = multi(v, 'Cities Covered');
  const cityLine = cities.length ? ('مدن التغطية لدينا في سجلكم: ' + cities.join('، ') + '.\n') : '';
  const subject = 'شراكة مع بيزنس بارتنر — إحالة عملاء لمساحاتكم وخدماتكم';
  const body = 'مرحباً ' + vendorName + '،\n\n'
    + 'نتواصل معكم من «بيزنس بارتنر» (Business Partner) — منصة سعودية تساعد الشركات ورواد الأعمال على إيجاد المكاتب ومساحات العمل والحلول العقارية المناسبة في المملكة.\n\n'
    + 'يصلنا يومياً طلبات من عملاء يبحثون عن مساحات وخدمات مثل ما تقدّمونه، ونودّ إدراجكم ضمن شبكة شركائنا لنرسل لكم طلبات التسعير (RFQ) المطابقة لنشاطكم ومدنكم.\n'
    + cityLine
    + '\nآلية التعامل:\n'
    + 'تعمل «بيزنس بارتنر» كوسيط بين العميل والمزوّد بعمولة قدرها 10% على قيمة الصفقة، ونطلب تضمينها ضمن عرض السعر الذي ترسلونه لنا للعميل (أي أن يكون السعر النهائي شاملاً عمولة بيزنس بارتنر 10%). بهذا يبقى العرض واضحاً وموحّداً أمام العميل.\n\n'
    + 'إن كنتم موافقين على هذه الآلية، يكفي الرد على هذا البريد بالموافقة، وسنبدأ بإرسال الطلبات المطابقة لكم فور توفرها.\n\n'
    + 'نتطلّع لشراكة مثمرة.\n\n'
    + 'مع التحية،\nفريق بيزنس بارتنر | Business Partner\nbusiness@businesspartner.sa';
  out.push({ json: { vendorPageId: v.id, email, vendorName, subject, body } });
}
return out;
